def validate_counts() -> None:
    """Raise AssertionError if item counts or smart_ids are wrong."""
    from collections import Counter

    counts = Counter((i["section_key"], i["item_type"]) for i in ITEMS)
    for section_key, targets in TARGET_COUNTS.items():
        for item_type, expected in targets.items():
            got = counts[(section_key, item_type)]
            assert got == expected, f"{section_key} {item_type}: {got} != {expected}"
    ids = [i["smart_id"] for i in ITEMS]
    assert len(ids) == len(set(ids)), "duplicate smart_id"


validate_counts()
